package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// 텍스트 생성 (Text Generation)
// ==================================================

// Generator 텍스트 생성기
type Generator struct {
	vocabSize   int
	modelDim    int
	maxSeqLen   int
	temperature float64
}

// NewGenerator 새로운 생성기 생성
func NewGenerator(vocabSize, modelDim, maxSeqLen int) *Generator {
	return &Generator{
		vocabSize:   vocabSize,
		modelDim:    modelDim,
		maxSeqLen:   maxSeqLen,
		temperature: 1.0,
	}
}

// SetTemperature 온도 설정 (낮을수록 결정적, 높을수록 창의적)
func (g *Generator) SetTemperature(temp float64) {
	if temp > 0 {
		g.temperature = temp
	}
}

// predictNextToken 다음 토큰 예측 (시뮬레이션)
func (g *Generator) predictNextToken(sequence []int) int {
	if len(sequence) == 0 {
		return rand.Intn(g.vocabSize)
	}

	// 마지막 토큰 기반으로 logits 생성 (시뮬레이션)
	lastToken := sequence[len(sequence)-1]
	logits := make([]float64, g.vocabSize)

	// 마지막 토큰과 관련된 토큰들에 높은 logits 부여
	for i := 0; i < g.vocabSize; i++ {
		// 토큰 간 유사도 (매우 간단한 시뮬레이션)
		distance := float64((lastToken - i) * (lastToken - i))
		logits[i] = math.Exp(-distance / float64(g.vocabSize*100)) * 10
	}

	// Softmax with temperature
	return g.sampleFromLogits(logits)
}

// sampleFromLogits logits에서 샘플링
func (g *Generator) sampleFromLogits(logits []float64) int {
	// Temperature 적용
	for i := range logits {
		logits[i] /= g.temperature
	}

	// Softmax
	maxLogit := logits[0]
	for _, l := range logits {
		if l > maxLogit {
			maxLogit = l
		}
	}

	sumExp := 0.0
	for _, l := range logits {
		sumExp += math.Exp(l - maxLogit)
	}

	probs := make([]float64, len(logits))
	for i, l := range logits {
		probs[i] = math.Exp(l-maxLogit) / sumExp
	}

	// Cumulative sampling
	r := rand.Float64()
	cumsum := 0.0

	for i, p := range probs {
		cumsum += p
		if r < cumsum {
			return i
		}
	}

	return len(logits) - 1
}

// GenerateGreedy Greedy decoding (항상 가장 확률 높은 토큰 선택)
func (g *Generator) GenerateGreedy(prompt []int, maxTokens int) []int {
	result := make([]int, len(prompt))
	copy(result, prompt)

	for i := 0; i < maxTokens && len(result) < g.maxSeqLen; i++ {
		nextToken := g.predictNextToken(result)
		result = append(result, nextToken)
	}

	return result
}

// GenerateWithSampling 샘플링으로 생성 (창의적)
func (g *Generator) GenerateWithSampling(prompt []int, maxTokens int) []int {
	result := make([]int, len(prompt))
	copy(result, prompt)

	for i := 0; i < maxTokens && len(result) < g.maxSeqLen; i++ {
		nextToken := g.predictNextToken(result)
		result = append(result, nextToken)
	}

	return result
}

// GenerateBeamSearch Beam search (상위 k개 경로 탐색)
func (g *Generator) GenerateBeamSearch(prompt []int, maxTokens, beamWidth int) []int {
	// 간단한 구현: greedy와 동일
	return g.GenerateGreedy(prompt, maxTokens)
}

// decodeTokens 토큰 ID를 텍스트로 변환
func decodeTokens(tokens []int, vocab map[string]int) string {
	// 역맵 생성
	revVocab := make(map[int]string)
	for k, v := range vocab {
		revVocab[v] = k
	}

	text := ""
	for _, tokenID := range tokens {
		if ch, ok := revVocab[tokenID]; ok {
			text += ch
		} else {
			text += fmt.Sprintf("[UNK:%d]", tokenID)
		}
	}

	return text
}

// encodeText 텍스트를 토큰 ID로 변환
func encodeText(text string, vocab map[string]int) []int {
	tokens := make([]int, 0)

	for _, ch := range text {
		if id, ok := vocab[string(ch)]; ok {
			tokens = append(tokens, id)
		}
	}

	return tokens
}

// GenerateText 사용자 친화적 텍스트 생성
func GenerateText(prompt string, maxTokens int, vocab map[string]int, temperature float64, method string) (string, []int) {
	generator := NewGenerator(len(vocab), 1024, 128)
	generator.SetTemperature(temperature)

	// 프롬프트 인코딩
	promptTokens := encodeText(prompt, vocab)

	var generatedTokens []int

	switch method {
	case "greedy":
		generatedTokens = generator.GenerateGreedy(promptTokens, maxTokens)
	case "sampling":
		generatedTokens = generator.GenerateWithSampling(promptTokens, maxTokens)
	case "beam":
		generatedTokens = generator.GenerateBeamSearch(promptTokens, maxTokens, 5)
	default:
		generatedTokens = generator.GenerateGreedy(promptTokens, maxTokens)
	}

	// 토큰 디코딩
	text := decodeTokens(generatedTokens, vocab)

	return text, generatedTokens
}

