package main

import (
	"fmt"
	"math"
)

// ==================================================
// 모델 평가 (Model Evaluation)
// ==================================================

// EvaluationResult 평가 결과
type EvaluationResult struct {
	ModelName         string
	Perplexity        float64
	TopKAccuracy      map[int]float64 // Top-1, Top-5, Top-10
	BLEU              float64
	RougeL            float64
	DataSize          int
	EvaluationTime    float64
	LossValues        []float64
	PerplexityTrend   []float64
}

// testModelEvaluation 모델 평가 테스트
func testModelEvaluation() {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  Model Evaluation - 모델 성능 평가                     ║")
	fmt.Println("║  Perplexity, Accuracy, BLEU, ROUGE                   ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	// 테스트 데이터 로드
	fmt.Println("[1/4] Loading test data...")
	valSamples, err := LoadBinaryData("data/val.bin", 100)
	if err != nil {
		fmt.Printf("❌ Failed: %v\n", err)
		return
	}

	vocab, _, err := LoadVocab("data/vocab.json")
	if err != nil {
		fmt.Printf("❌ Failed: %v\n", err)
		return
	}

	fmt.Printf("✅ Loaded %d validation samples, %d vocab tokens\n\n", len(valSamples), len(vocab))

	// Test 1: Medium Model (256D) 평가
	fmt.Println("[2/4] Test 1: Medium Model (256D, 4 layers) Evaluation")
	fmt.Println("════════════════════════════════════════════════════════")

	result1 := evaluateModel(
		"Medium Model (256D, 4L)",
		valSamples,
		vocab,
		256,
		4,
		0.001,
	)

	printEvaluationResult(result1)

	// Test 2: Large Model (512D) 평가
	fmt.Println("\n[3/4] Test 2: Large Model (512D, 6 layers) Evaluation")
	fmt.Println("════════════════════════════════════════════════════════")

	result2 := evaluateModel(
		"Large Model (512D, 6L)",
		valSamples,
		vocab,
		512,
		6,
		0.0005,
	)

	printEvaluationResult(result2)

	// Test 3: XLarge Model (1024D) 평가
	fmt.Println("\n[4/4] Test 3: XLarge Model (1024D, 8 layers) Evaluation")
	fmt.Println("════════════════════════════════════════════════════════")

	result3 := evaluateModel(
		"XLarge Model (1024D, 8L)",
		valSamples,
		vocab,
		1024,
		8,
		0.0001,
	)

	printEvaluationResult(result3)

	// 최종 비교
	fmt.Println("\n════════════════════════════════════════════════════════")
	fmt.Println("🏆 MODEL COMPARISON SUMMARY")
	fmt.Println("════════════════════════════════════════════════════════\n")

	results := []EvaluationResult{result1, result2, result3}

	// 헤더
	fmt.Println("Model            | Perplexity | Top-1 Acc | Top-5 Acc | BLEU   | ROUGE-L")
	fmt.Println("-----------------|------------|-----------|-----------|--------|--------")

	for _, r := range results {
		fmt.Printf("%-16s | %10.2f | %9.1f%% | %9.1f%% | %.4f | %.4f\n",
			r.ModelName[:min(len(r.ModelName), 16)],
			r.Perplexity,
			r.TopKAccuracy[1]*100,
			r.TopKAccuracy[5]*100,
			r.BLEU,
			r.RougeL)
	}

	// 최고 성능 모델
	fmt.Println("\n🥇 Best Performing Model:")
	bestModel := results[0]
	for _, r := range results {
		if r.Perplexity < bestModel.Perplexity {
			bestModel = r
		}
	}

	fmt.Printf("   Model: %s\n", bestModel.ModelName)
	fmt.Printf("   Perplexity: %.2f\n", bestModel.Perplexity)
	fmt.Printf("   Top-1 Accuracy: %.1f%%\n", bestModel.TopKAccuracy[1]*100)
	fmt.Printf("   BLEU Score: %.4f\n", bestModel.BLEU)

	// 트렌드 분석
	fmt.Println("\n📈 Perplexity Trend over Evaluation:")
	for i, ppl := range bestModel.PerplexityTrend {
		barLen := int((bestModel.PerplexityTrend[0]-ppl)/bestModel.PerplexityTrend[0]*40 + 1)
		if barLen > 40 {
			barLen = 40
		}
		if barLen < 1 {
			barLen = 1
		}

		bar := ""
		for j := 0; j < barLen; j++ {
			bar += "█"
		}

		fmt.Printf("  Batch %d: %s %.2f\n", i+1, bar, ppl)
	}

	fmt.Println("\n✅ Model evaluation complete!")
}

// evaluateModel 모델 평가
func evaluateModel(modelName string, samples [][]int, vocab map[string]int, dModel, numLayers int, lr float64) EvaluationResult {
	fmt.Printf("\nEvaluating: %s\n", modelName)
	fmt.Printf("  Model Dim: %d, Num Layers: %d, LR: %.6f\n\n", dModel, numLayers, lr)

	result := EvaluationResult{
		ModelName:        modelName,
		DataSize:         len(samples),
		TopKAccuracy:     make(map[int]float64),
		LossValues:       make([]float64, 0),
		PerplexityTrend:  make([]float64, 0),
	}

	// 배치별 평가
	totalLoss := 0.0
	totalCorrect := 0
	totalTop5 := 0
	totalTop10 := 0
	totalSamples := 0

	batchSize := 32
	numBatches := (len(samples) + batchSize - 1) / batchSize

	for batch := 0; batch < numBatches; batch++ {
		start := batch * batchSize
		end := start + batchSize
		if end > len(samples) {
			end = len(samples)
		}

		batchLoss := 0.0
		batchCorrect := 0

		for _, seq := range samples[start:end] {
			if len(seq) < 2 {
				continue
			}

			// 손실 계산 (시뮬레이션)
			// 더 큰 모델 → 더 낮은 손실
			sizeFactor := math.Exp(-float64(dModel) / 500.0)
			layerFactor := math.Exp(-float64(numLayers) / 8.0)

			baseLoss := 100.0
			loss := baseLoss * sizeFactor * layerFactor
			loss += (float64(batch % 10)) * 0.5 // 약간의 변동

			batchLoss += loss
			totalLoss += loss

			// 정확도 (시뮬레이션)
			if len(seq) > 0 && seq[0]%2 == 0 {
				batchCorrect++
				totalCorrect++
			}

			// Top-5, Top-10 (시뮬레이션)
			if len(seq) > 1 && seq[0]%5 <= 1 {
				totalTop5++
			}
			if len(seq) > 1 && seq[0]%10 <= 2 {
				totalTop10++
			}

			totalSamples++
		}

		if len(samples[start:end]) > 0 {
			batchLoss /= float64(len(samples[start:end]))
			result.LossValues = append(result.LossValues, batchLoss)

			// Perplexity
			ppl := math.Exp(batchLoss)
			result.PerplexityTrend = append(result.PerplexityTrend, ppl)
		}

		// 진행 상황
		if batch%3 == 0 {
			fmt.Printf("  [Batch %d/%d] Loss: %.4f, Acc: %.1f%%\r", batch+1, numBatches, batchLoss, float64(batchCorrect)/float64(len(samples[start:end]))*100)
		}
	}

	// 최종 메트릭 계산
	if totalSamples > 0 {
		avgLoss := totalLoss / float64(totalSamples)
		result.Perplexity = math.Exp(avgLoss)
		result.TopKAccuracy[1] = float64(totalCorrect) / float64(totalSamples)
		result.TopKAccuracy[5] = float64(totalTop5) / float64(totalSamples)
		result.TopKAccuracy[10] = float64(totalTop10) / float64(totalSamples)
	}

	// BLEU, ROUGE 시뮬레이션
	result.BLEU = 0.25 + math.Exp(-result.Perplexity/100.0)*0.5
	result.RougeL = 0.35 + math.Exp(-result.Perplexity/100.0)*0.4

	result.EvaluationTime = 5.2 // 시뮬레이션

	fmt.Printf("\n  ✅ Evaluation complete\n")

	return result
}

// printEvaluationResult 평가 결과 출력
func printEvaluationResult(result EvaluationResult) {
	fmt.Printf("\n🎯 %s\n", result.ModelName)
	fmt.Printf("════════════════════════════════════════════════════════\n\n")

	fmt.Printf("📊 Main Metrics:\n")
	fmt.Printf("  Perplexity:           %.2f\n", result.Perplexity)
	fmt.Printf("  BLEU Score:           %.4f\n", result.BLEU)
	fmt.Printf("  ROUGE-L Score:        %.4f\n\n", result.RougeL)

	fmt.Printf("📈 Accuracy Metrics:\n")
	fmt.Printf("  Top-1 Accuracy:       %.1f%%\n", result.TopKAccuracy[1]*100)
