	text := string(content)
	fmt.Printf("✅ Loaded %d characters\n\n", len(text))

	// 2. 문자 단위 토크나이제이션 + 어휘집 구축
	fmt.Println("[2/3] Building vocabulary...")
	vocab := make(map[string]int)
	tokens := make([]int, 0)
	vocabIndex := 0

	for _, ch := range text {
		charStr := string(ch)

		// 어휘집에 없으면 추가
		if _, ok := vocab[charStr]; !ok {
			vocab[charStr] = vocabIndex
			vocabIndex++
		}

		// 토큰 ID 추가
		tokens = append(tokens, vocab[charStr])
	}

	fmt.Printf("✅ Vocabulary size: %d\n", len(vocab))
	fmt.Printf("✅ Total tokens: %d\n\n", len(tokens))

	// 3. 통계
	fmt.Println("[3/3] Statistics:")
	fmt.Printf("   Compression ratio: %.1f%%\n", float64(len(text))/float64(len(tokens))*100)
	fmt.Printf("   Avg token per char: %.2f\n\n", float64(len(tokens))/float64(len(text)))

